create table finished_product (id uuid primary key, organization_id uuid not null references organization(id) on delete cascade, name varchar(180) not null, sku varchar(80), unit varchar(24) not null, active boolean not null default true, created_at timestamp with time zone not null, unique(organization_id,name));
create table recipe (id uuid primary key, organization_id uuid not null references organization(id) on delete cascade, product_id uuid not null references finished_product(id), name varchar(180) not null, yield_quantity numeric(19,3) not null check(yield_quantity>0), yield_unit varchar(24) not null, active boolean not null default true, created_at timestamp with time zone not null);
create table recipe_ingredient (id uuid primary key, recipe_id uuid not null references recipe(id) on delete cascade, ingredient_id uuid not null references ingredient(id), quantity numeric(19,3) not null check(quantity>0), unit varchar(24) not null, unique(recipe_id,ingredient_id));
create table production_batch (id uuid primary key, organization_id uuid not null references organization(id) on delete cascade, recipe_id uuid not null references recipe(id), location_id uuid not null references location(id), batch_number varchar(120) not null, output_quantity numeric(19,3) not null check(output_quantity>0), output_unit varchar(24) not null, produced_at timestamp with time zone not null, note varchar(500), unique(organization_id,batch_number));
create table production_consumption (id uuid primary key, production_batch_id uuid not null references production_batch(id) on delete cascade, lot_id uuid not null references inventory_lot(id), location_id uuid not null references location(id), quantity numeric(19,3) not null check(quantity>0), unit varchar(24) not null);
create index idx_production_batch_org on production_batch(organization_id);
